// Map.tsx con soporte para entorno local y producción (rutas pmtiles adaptadas)
import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import { Protocol } from 'pmtiles';
import 'maplibre-gl/dist/maplibre-gl.css';

type MapProps = {
  layersVisibility: { [layerId: string]: boolean };
};

const Map: React.FC<MapProps> = ({ layersVisibility }) => {
  const mapRef = useRef<maplibregl.Map | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);

  const isLocal = window.location.hostname === 'localhost';

  const getURL = (filename: string) => {
    return isLocal ? `/data/${filename}` : `pmtiles://data/${filename}`;
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const protocol = new Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);

    const map = new maplibregl.Map({
      container,
      style: 'https://api.maptiler.com/maps/01976666-b449-7252-86b5-3e7b3213a9e6/style.json?key=QAha5pFBxf4hGa8Jk5zv',
      center: [-101.98896, 23.07870],
      zoom: 4.47,
      attributionControl: false,
    });

    map.on('load', () => {
      map.addControl(new maplibregl.AttributionControl({
        customAttribution: 'Mapa INPI',
        compact: true
      }), 'bottom-right');

      const sources = [
        'LocalidadesSedeINPI',
        'PresidenciasMunicipales',
        'PuntosWiFiCFE',
        'RegionesMesas',
        'asambleas_consulta',
      ];

      sources.forEach(src => {
        map.addSource(src, {
          type: 'vector',
          url: getURL(`${src}.pmtiles`)
        });
      });

      // Aquí continúa tu lógica de addLayer y eventos...
      // Puedes seguir usando map.addLayer({ id: 'LocalidadesSedeINPI', ... })
      // y funcionará igual tanto en desarrollo como en producción.

      // El resto del código continúa igual...
    });

    mapRef.current = map;

    return () => {
      map.remove();
      maplibregl.removeProtocol('pmtiles');
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    Object.entries(layersVisibility).forEach(([id, visible]) => {
      const vis = visible ? 'visible' : 'none';
      try {
        if (map.getLayer(id)) {
          map.setLayoutProperty(id, 'visibility', vis);
        }
      } catch {}
    });
  }, [layersVisibility]);

  return <div ref={containerRef} style={{ width: '100%', height: '100vh' }} />;
};

export default Map;
